function I(n,cls=''){return `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]||icons.leaf}"/></svg>`;}
const nav=[['home','home','學習首頁'],['kana','kana','五十音讀寫'],['words','book','單字聽讀'],['grammar','layers','文法結構'],['conversation','chat','日常會話'],['reading','article','短文閱讀'],['upload','upload','文章研究室'],['games','game','練習與闖關']];
